agent_detail.agent_sql:
SELECT ?bond_type (COUNT(?b) AS ?n) WHERE {
  ?b a <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Bond> ;
     <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Bond/bond_type> ?bond_type .
}
GROUP BY ?bond_type
ORDER BY DESC(?n)
LIMIT 1

SELECT DISTINCT ?molecule_id WHERE {
  ?m a <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Molecule> ;
     <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Molecule/molecule_id> ?molecule_id ;
     <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Molecule/label> ?label .
  FILTER(?label = "+")
  ?b a <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Bond> ;
     <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Bond/molecule_id> ?molecule_id ;
     <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Bond/bond_type> ?bond_type .
  FILTER(?bond_type = "#")
}

SELECT ?label WHERE {
  ?atom a <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Atom> ;
        <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Atom/element> ?element ;
        <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Atom/molecule_id> ?molId .
  FILTER(LCASE(?element) = "h")
  ?mol a <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Molecule> ;
       <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Molecule/molecule_id> ?molId ;
       <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Molecule/label> ?label .
}
GROUP BY ?label
ORDER BY DESC(COUNT(?atom))
LIMIT 1

SELECT DISTINCT ?element WHERE {
  ?c a <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Connected> ;
     <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Connected/bond_id> "TR004_8_9" ;
     <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Connected/atom_id> ?aid .
  ?a a <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Atom> ;
     <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Atom/atom_id> ?aid ;
     <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Atom/element> ?element .
}

SELECT (AVG(?cnt) AS ?avgSingleBonds)
WHERE {
  {
    SELECT ?m (COUNT(?b) AS ?cnt)
    WHERE {
      ?mol a <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Molecule> ;
           <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Molecule/molecule_id> ?m ;
           <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Molecule/label> "+" .
      ?b a <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Bond> ;
         <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Bond/molecule_id> ?m ;
         <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Bond/bond_type> "-" .
    }
    GROUP BY ?m
  }
}

SELECT (AVG(?cnt) AS ?avgOxygenAtoms)
WHERE {
  {
    SELECT ?m (COUNT(?a) AS ?cnt) WHERE {
      { SELECT DISTINCT ?m WHERE {
          ?b a <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Bond> ;
             <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Bond/bond_type> "-" ;
             <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Bond/hasMolecule> ?m .
        } }
      OPTIONAL {
        ?a a <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Atom> ;
           <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Atom/hasMolecule> ?m ;
           <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Atom/element> "o" .
      }
    }
    GROUP BY ?m
  }
}

SELECT ((SUM(IF(?element = "c", xsd:decimal(1), xsd:decimal(0))) * 100.0) / COUNT(?atom) AS ?percentage)
WHERE {
  ?atom a <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Atom> ;
        <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Atom/element> ?element ;
        <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Atom/molecule_id> ?mid .
  FILTER EXISTS {
    ?bond a <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Bond> ;
          <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Bond/molecule_id> ?mid ;
          <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Bond/bond_type> "=" .
  }
}

SELECT ?element WHERE {
  {
    SELECT ?element (COUNT(?atom) AS ?cnt) WHERE {
      ?atom a <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Atom> ;
            <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Atom/element> ?element ;
            <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Atom/molecule_id> ?mid .
      ?mol a <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Molecule> ;
           <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Molecule/molecule_id> ?mid ;
           <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Molecule/label> ?label .
      FILTER(?label = "-")
    }
    GROUP BY ?element
  }
}
ORDER BY ?cnt
LIMIT 1

SELECT ?bond_type WHERE {
  ?c a <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Connected> ;
     <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Connected/atom_id> "TR004_8" ;
     <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Connected/atom_id2> "TR004_20" ;
     <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Connected/bond_id> ?bond_id .
  ?b a <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Bond> ;
     <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Bond/bond_id> ?bond_id ;
     <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Bond/bond_type> ?bond_type .
}

SELECT (COUNT(DISTINCT ?a) AS ?n) WHERE {
  ?a a <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Atom> ;
     <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Atom/element> ?e ;
     <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Atom/molecule_id> ?m .
  FILTER(?e IN ("i", "s"))
  ?b a <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Bond> ;
     <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Bond/bond_type> "-" ;
     <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Bond/molecule_id> ?m .
}

SELECT ?element WHERE {
  {
    SELECT ?element (COUNT(?atom) AS ?cnt) WHERE {
      ?atom a <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Atom> ;
            <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Atom/molecule_id> "TR000" ;
            <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Atom/element> ?element .
    }
    GROUP BY ?element
    ORDER BY DESC(?cnt)
    LIMIT 3
  }
}
ORDER BY ?element

SELECT ?element ?label WHERE {
  ?atom a <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Atom> ;
        <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Atom/molecule_id> "TR060" ;
        <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Atom/element> ?element .
  ?molecule a <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Molecule> ;
        <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Molecule/molecule_id> "TR060" ;
        <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Molecule/label> ?label .
}

SELECT DISTINCT ?molecule_id WHERE {
  ?m a <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Molecule> ;
     <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Molecule/molecule_id> ?molecule_id ;
     <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Molecule/label> ?label .
  FILTER(?label = "-")
  ?b a <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Bond> ;
     <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Bond/molecule_id> ?molecule_id ;
     <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Bond/bond_type> ?bond_type .
  FILTER(?bond_type = "-")
}
ORDER BY ?molecule_id
LIMIT 3

SELECT ?bond_type ?label WHERE {
  {
    SELECT ?bond_type (COUNT(?b) AS ?cnt) WHERE {
      ?b a <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Bond> ;
         <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Bond/molecule_id> "TR010" ;
         <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Bond/bond_type> ?bond_type .
    }
    GROUP BY ?bond_type
    ORDER BY DESC(?cnt)
    LIMIT 1
  }
  ?m a <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Molecule> ;
     <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Molecule/molecule_id> "TR010" ;
     <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Molecule/label> ?label .
}

SELECT (xsd:decimal(SUM(IF(?bt = "=", 1, 0))) / xsd:decimal(COUNT(*)) * 100.0 AS ?pct)
WHERE {
  ?b a <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Bond> ;
     <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Bond/molecule_id> "TR008" ;
     <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Bond/bond_type> ?bt .
}

SELECT (COUNT(DISTINCT ?bond) AS ?n) WHERE {
  ?bond a <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Bond> ;
        <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Bond/molecule_id> "TR009" ;
        <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Bond/bond_id> ?bondId .
  ?conn a <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Connected> ;
        <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Connected/bond_id> ?bondId .
  { ?conn <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Connected/atom_id> "TR009_12" }
  UNION
  { ?conn <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Connected/atom_id2> "TR009_12" }
}

SELECT (ROUND((SUM(IF(?label = "+", 1.0, 0.0)) * 100000) / COUNT(*)) / 1000 AS ?percentage)
WHERE {
  ?m a <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Molecule> ;
     <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Molecule/label> ?label .
}

SELECT ?bond_type ?atom_id ?atom_id2 WHERE {
  ?b a <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Bond> ;
     <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Bond/bond_id> "TR001_6_9" ;
     <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Bond/bond_type> ?bond_type .
  ?c a <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Connected> ;
     <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Connected/bond_id> "TR001_6_9" ;
     <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Connected/atom_id> ?atom_id ;
     <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Connected/atom_id2> ?atom_id2 .
}

SELECT ?element WHERE {
  ?atom a <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Atom> ;
        <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Atom/molecule_id> "TR004" ;
        <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Atom/element> ?element .
}

SELECT (COUNT(*) AS ?n) WHERE {
  ?c a <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Connected> ;
     <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Connected/atom_id> ?aid .
  FILTER(REGEX(?aid, "_19$"))
}

SELECT (xsd:decimal(?noFluorine) * 100.0 / xsd:decimal(?total) AS ?percentage)
WHERE {
  {
    SELECT (COUNT(DISTINCT ?m) AS ?total)
    WHERE {
      ?m a <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Molecule> ;
         <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Molecule/label> "+" .
    }
  }
  {
    SELECT (COUNT(DISTINCT ?m2) AS ?noFluorine)
    WHERE {
      ?m2 a <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Molecule> ;
          <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Molecule/label> "+" ;
          <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Molecule/molecule_id> ?mid2 .
      FILTER NOT EXISTS {
        ?a a <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Atom> ;
           <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Atom/molecule_id> ?mid2 ;
           <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Atom/element> "f" .
      }
    }
  }
}

SELECT (ROUND(((?h * 100.0) / ?total) * 10000) / 10000 AS ?percentage)
WHERE {
  {
    SELECT (SUM(IF(?element = "h", 1, 0)) AS ?h) (COUNT(?a) AS ?total)
    WHERE {
      ?a a <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Atom> ;
         <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Atom/molecule_id> "TR206" ;
         <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Atom/element> ?element .
    }
  }
}

SELECT DISTINCT ?molecule_id WHERE {
  ?atom a <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Atom> ;
        <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Atom/atom_id> ?atomId ;
        <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Atom/molecule_id> ?molecule_id .
  ?molecule a <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Molecule> ;
            <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Molecule/molecule_id> ?molecule_id ;
            <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Molecule/label> ?label .
  BIND(STRAFTER(STR(?atomId), "_") AS ?suffix)
  FILTER(xsd:integer(?suffix) >= 21 && xsd:integer(?suffix) <= 25)
  FILTER(?label = "+")
}

SELECT ?label WHERE {
  {
    SELECT ?molecule_id (COUNT(?bond) AS ?cnt) WHERE {
      ?bond a <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Bond> ;
            <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Bond/bond_type> "=" ;
            <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Bond/molecule_id> ?molecule_id .
    }
    GROUP BY ?molecule_id
    ORDER BY DESC(?cnt)
    LIMIT 1
  }
  ?m a <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Molecule> ;
     <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Molecule/molecule_id> ?molecule_id ;
     <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Molecule/label> ?label .
}

SELECT DISTINCT ?bond_id
WHERE {
  ?c a <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Connected> ;
     <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Connected/atom_id> ?a1 ;
     <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Connected/atom_id2> ?a2 ;
     <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Connected/bond_id> ?bond_id .

  ?atom1 a <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Atom> ;
         <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Atom/atom_id> ?a1 ;
         <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Atom/element> ?e1 .

  ?atom2 a <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Atom> ;
         <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Atom/atom_id> ?a2 ;
         <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Atom/element> ?e2 .

  FILTER(
    (LCASE(?e1) = "p" && LCASE(?e2) = "n") ||
    (LCASE(?e1) = "n" && LCASE(?e2) = "p")
  )
}

SELECT ?element WHERE {
  ?a a <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Atom> ;
     <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Atom/atom_id> ?atomId ;
     <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Atom/element> ?element .
  FILTER NOT EXISTS {
    ?c1 a <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Connected> ;
        <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Connected/atom_id> ?atomId .
  }
  FILTER NOT EXISTS {
    ?c2 a <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Connected> ;
        <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Connected/atom_id2> ?atomId .
  }
}

SELECT ?atom_id ?atom_id2 WHERE {
  ?bond a <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Bond> ;
        <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Bond/molecule_id> "TR041" ;
        <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Bond/bond_type> "#" ;
        <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Bond/bond_id> ?bond_id .
  ?conn a <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Connected> ;
        <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Connected/bond_id> ?bond_id ;
        <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Connected/atom_id> ?atom_id ;
        <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Connected/atom_id2> ?atom_id2 .
}

SELECT (AVG(?cnt) AS ?avgBonds) WHERE {
  {
    SELECT ?atomId (COUNT(?conn) AS ?cnt) WHERE {
      ?atom a <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Atom> ;
            <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Atom/element> "i" ;
            <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Atom/atom_id> ?atomId .
      ?conn a <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Connected> ;
            <http://bird-bird_toxicology-ontology-20260810-000847/ontology/vkg-bird_toxicology/Connected/atom_id> ?atomId .
    }
    GROUP BY ?atomId
  }
